import{_ as o,o as a,c as s,a2 as n}from"./chunks/framework.CPzUcv0I.js";const g=JSON.parse('{"title":"FAQ and Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/players/troubleshooting.md","filePath":"guide/players/troubleshooting.md"}'),r={name:"guide/players/troubleshooting.md"};function t(i,e,l,c,u,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="faq-and-troubleshooting" tabindex="-1">FAQ and Troubleshooting <a class="header-anchor" href="#faq-and-troubleshooting" aria-label="Permalink to &quot;FAQ and Troubleshooting&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Support-GitHub%20Issues-blue.svg" alt="Support"><img src="https://img.shields.io/badge/Status-Open%20Source-green.svg" alt="Status"></div><p>This guide collects answers to frequently asked questions and troubleshooting advice for resolving common issues with Gens Launcher.</p><hr><h2 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h2><h3 id="does-gens-launcher-support-offline-accounts" tabindex="-1">Does Gens Launcher support offline accounts? <a class="header-anchor" href="#does-gens-launcher-support-offline-accounts" aria-label="Permalink to &quot;Does Gens Launcher support offline accounts?&quot;">​</a></h3><p><strong>Yes.</strong> While we strongly recommend playing with an official Microsoft account for multiplayer skin support and verified server access, Gens Launcher includes full support for offline profiles on local area networks.</p><h3 id="why-does-windows-display-the-blue-smartscreen-warning-on-install" tabindex="-1">Why does Windows display the blue SmartScreen warning on install? <a class="header-anchor" href="#why-does-windows-display-the-blue-smartscreen-warning-on-install" aria-label="Permalink to &quot;Why does Windows display the blue SmartScreen warning on install?&quot;">​</a></h3><p>Gens Launcher is an independent, non-commercial open-source project. Acquiring commercial EV Code Signing certificates costs hundreds of dollars per year. Simply click <strong>&quot;More info&quot;</strong> and select <strong>&quot;Run anyway&quot;</strong>. The complete codebase is public on GitHub.</p><h3 id="are-my-microsoft-credentials-secure" tabindex="-1">Are my Microsoft credentials secure? <a class="header-anchor" href="#are-my-microsoft-credentials-secure" aria-label="Permalink to &quot;Are my Microsoft credentials secure?&quot;">​</a></h3><p><strong>Yes, completely.</strong> Gens Launcher uses Microsoft&#39;s official OAuth2 Device Code Flow. The application never sees or touches your password. Session tokens are encrypted on disk via OS-level security APIs (<code>safeStorage</code> or PBKDF2 with 600,000 iterations and AES-256-GCM).</p><h3 id="is-gens-launcher-free" tabindex="-1">Is Gens Launcher free? <a class="header-anchor" href="#is-gens-launcher-free" aria-label="Permalink to &quot;Is Gens Launcher free?&quot;">​</a></h3><p><strong>Yes, 100% free with no ads.</strong> The project is licensed under the MIT License and includes zero telemetry or data tracking.</p><hr><h2 id="common-issues-and-solutions" tabindex="-1">Common Issues and Solutions <a class="header-anchor" href="#common-issues-and-solutions" aria-label="Permalink to &quot;Common Issues and Solutions&quot;">​</a></h2><h3 id="_1-game-crashes-or-fails-to-launch-java-errors" tabindex="-1">1. Game crashes or fails to launch (Java errors) <a class="header-anchor" href="#_1-game-crashes-or-fails-to-launch-java-errors" aria-label="Permalink to &quot;1. Game crashes or fails to launch (Java errors)&quot;">​</a></h3><ul><li><strong>Verify your Java version:</strong> Minecraft 1.20.5+ requires Java 21 or Java 25. Minecraft 1.18 to 1.20.4 requires Java 17. Minecraft 1.16 requires Java 8.<br> Open <em>Instance Settings</em> and let Gens Launcher automatically download and assign the appropriate runtime.</li><li><strong>Inspect memory allocation (RAM):</strong> Allocating less than 2 GB can trigger <code>java.lang.OutOfMemoryError</code>. Avoid assigning more than half of your total system RAM to leave room for your operating system.</li><li><strong>Conflicting mods:</strong> Check the instance <em>Logs</em> tab to locate the mod causing the crash (look for <code>CrashReport</code> or <code>MixinApplyError</code>). Disable the problematic mod using the toggle switch in the Mods tab.</li></ul><h3 id="_2-horizon-cloud-sync-fails" tabindex="-1">2. Horizon Cloud Sync fails <a class="header-anchor" href="#_2-horizon-cloud-sync-fails" aria-label="Permalink to &quot;2. Horizon Cloud Sync fails&quot;">​</a></h3><ul><li><strong>Verify Internet connectivity:</strong> When offline, the launcher automatically defuses background sync tasks to avoid hanging the UI.</li><li><strong>Active lock message (horizon.lock):</strong> If the game crashed unexpectedly or is still active on another machine, an atomic lock protects your files. If you are certain no process is running, unlock the instance via the <em>Purge Lock</em> button in Advanced Settings.</li><li><strong>Cloud token expiration:</strong> If your cloud provider revoked permissions, simply disconnect and reconnect the provider in <em>Horizon Settings</em>.</li></ul><h3 id="_3-macos-installation-issues" tabindex="-1">3. macOS installation issues <a class="header-anchor" href="#_3-macos-installation-issues" aria-label="Permalink to &quot;3. macOS installation issues&quot;">​</a></h3><ul><li><strong>&quot;Application cannot be opened because it is from an unidentified developer&quot;:</strong> Right-click the Gens Launcher icon in <code>/Applications</code>, choose <strong>Open</strong>, and confirm by clicking <strong>Open</strong> again. This prompt only occurs on the first launch.</li></ul><hr><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If you continue experiencing issues:</p><ol><li>Gather your error logs via the <em>Help / Logs</em> menu.</li><li>Open a public ticket on the <a href="https://github.com/WilliamBossard/Gens-Launcher/issues" target="_blank" rel="noreferrer">Gens-Launcher GitHub Issues</a> repository.</li></ol>',25)])])}const p=o(r,[["render",t]]);export{g as __pageData,p as default};
